CREATE TYPE "BlogPostStatus" AS ENUM ('DRAFT','PUBLISHED','ARCHIVED');
CREATE TYPE "BlogCommentStatus" AS ENUM ('PENDING','APPROVED','REJECTED');
CREATE TYPE "BlogReactionType" AS ENUM ('LIKE','DISLIKE');
CREATE TABLE "BlogCategory" ("id" TEXT NOT NULL,"slug" TEXT NOT NULL,"nameFa" TEXT NOT NULL,"nameEn" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "BlogCategory_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "BlogCategory_slug_key" ON "BlogCategory"("slug");
CREATE TABLE "BlogTag" ("id" TEXT NOT NULL,"slug" TEXT NOT NULL,"nameFa" TEXT NOT NULL,"nameEn" TEXT NOT NULL, CONSTRAINT "BlogTag_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "BlogTag_slug_key" ON "BlogTag"("slug");
CREATE TABLE "BlogPost" ("id" TEXT NOT NULL,"slug" TEXT NOT NULL,"titleFa" TEXT NOT NULL,"titleEn" TEXT NOT NULL,"excerptFa" TEXT NOT NULL,"excerptEn" TEXT NOT NULL,"contentFa" TEXT NOT NULL,"contentEn" TEXT NOT NULL,"coverImage" TEXT,"status" "BlogPostStatus" NOT NULL DEFAULT 'DRAFT',"authorId" TEXT NOT NULL,"categoryId" TEXT,"seoTitleFa" TEXT,"seoTitleEn" TEXT,"seoDescriptionFa" TEXT,"seoDescriptionEn" TEXT,"publishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "BlogPost_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "BlogPost_slug_key" ON "BlogPost"("slug"); CREATE INDEX "BlogPost_status_publishedAt_idx" ON "BlogPost"("status","publishedAt"); CREATE INDEX "BlogPost_categoryId_idx" ON "BlogPost"("categoryId");
CREATE TABLE "BlogImage" ("id" TEXT NOT NULL,"postId" TEXT NOT NULL,"key" TEXT NOT NULL,"url" TEXT NOT NULL,"altFa" TEXT,"altEn" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "BlogImage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "BlogComment" ("id" TEXT NOT NULL,"postId" TEXT NOT NULL,"userId" TEXT,"body" TEXT NOT NULL,"status" "BlogCommentStatus" NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "BlogComment_pkey" PRIMARY KEY ("id")); CREATE INDEX "BlogComment_postId_status_idx" ON "BlogComment"("postId","status");
CREATE TABLE "BlogReaction" ("id" TEXT NOT NULL,"postId" TEXT NOT NULL,"userId" TEXT NOT NULL,"type" "BlogReactionType" NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "BlogReaction_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "BlogReaction_postId_userId_key" ON "BlogReaction"("postId","userId");
CREATE TABLE "BlogRating" ("id" TEXT NOT NULL,"postId" TEXT NOT NULL,"userId" TEXT NOT NULL,"value" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "BlogRating_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "BlogRating_postId_userId_key" ON "BlogRating"("postId","userId");
CREATE TABLE "BlogView" ("id" TEXT NOT NULL,"postId" TEXT NOT NULL,"visitorKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "BlogView_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "BlogView_postId_visitorKey_key" ON "BlogView"("postId","visitorKey"); CREATE INDEX "BlogView_postId_createdAt_idx" ON "BlogView"("postId","createdAt");
CREATE TABLE "_BlogPostToBlogTag" ("A" TEXT NOT NULL,"B" TEXT NOT NULL); CREATE UNIQUE INDEX "_BlogPostToBlogTag_AB_unique" ON "_BlogPostToBlogTag"("A","B"); CREATE INDEX "_BlogPostToBlogTag_B_index" ON "_BlogPostToBlogTag"("B");
ALTER TABLE "_BlogPostToBlogTag" ADD CONSTRAINT "_BlogPostToBlogTag_A_fkey" FOREIGN KEY ("A") REFERENCES "BlogPost"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "_BlogPostToBlogTag" ADD CONSTRAINT "_BlogPostToBlogTag_B_fkey" FOREIGN KEY ("B") REFERENCES "BlogTag"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "BlogPost" ADD CONSTRAINT "BlogPost_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "BlogPost" ADD CONSTRAINT "BlogPost_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "BlogCategory"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "BlogImage" ADD CONSTRAINT "BlogImage_postId_fkey" FOREIGN KEY ("postId") REFERENCES "BlogPost"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "BlogComment" ADD CONSTRAINT "BlogComment_postId_fkey" FOREIGN KEY ("postId") REFERENCES "BlogPost"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "BlogComment" ADD CONSTRAINT "BlogComment_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "BlogReaction" ADD CONSTRAINT "BlogReaction_postId_fkey" FOREIGN KEY ("postId") REFERENCES "BlogPost"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "BlogReaction" ADD CONSTRAINT "BlogReaction_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "BlogRating" ADD CONSTRAINT "BlogRating_postId_fkey" FOREIGN KEY ("postId") REFERENCES "BlogPost"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "BlogRating" ADD CONSTRAINT "BlogRating_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "BlogView" ADD CONSTRAINT "BlogView_postId_fkey" FOREIGN KEY ("postId") REFERENCES "BlogPost"("id") ON DELETE CASCADE ON UPDATE CASCADE;
